graph = inputs.get('graph') if is_dict(inputs.get('graph')) else {}
alert = inputs.get('alert') if is_dict(inputs.get('alert')) else {}
limit = int(inputs.get('max_items') or 15)
me = f"alert_{inputs.get('alert_id')}"

nodes = {}
for item in graph.get('nodes') or []:
    if is_dict(item) and is_str(item.get('id')):
        nodes[item['id']] = item
links = {}
for edge in graph.get('edges') or []:
    if not is_dict(edge) or edge.get('from') not in nodes or edge.get('to') not in nodes:
        continue
    links[edge['from']] = (links.get(edge['from']) or []) + [edge['to']]
    links[edge['to']] = (links.get(edge['to']) or []) + [edge['from']]

# The IOCs and assets of the new alert; every one in the graph when the
# alert itself is not drawn (the graph is built from them)
mine = links.get(me)
if mine is None:
    mine = [k for k in nodes if nodes[k].get('group') in ('ioc', 'asset')]

def shared(node_id):
    found = []
    for other in links.get(node_id) or []:
        if other in mine:
            label = str(nodes[other].get('label') or other)
            if label not in found:
                found.append(label)
    return found

def number(node_id, prefix):
    m = re_fullmatch(prefix + '_(\\d+)', node_id)
    return int(m['groups'][0]) if m is not None else None

alerts = []
cases = []
for node_id in nodes:
    item = nodes[node_id]
    label = str(item.get('label') or '')
    if item.get('group') == 'alert' and node_id != me:
        alert_id = number(node_id, 'alert')
        if alert_id is None:
            continue
        verdict = re_match('(?:\\[Closed\\])?\\[([^\\]]+)\\]', label)
        alerts.append({
            'id': alert_id,
            'title': re_sub('^(?:\\[Closed\\])?(?:\\[[^\\]]*\\])?\\s*', '', label)[:200],
            'closed': label.startswith('[Closed]'),
            'resolution': verdict['groups'][0] if verdict is not None else None,
            'shared': shared(node_id)[:10],
        })
    elif item.get('group') == 'case':
        case_id = number(node_id, 'case')
        if case_id is None:
            continue
        cases.append({
            'id': case_id,
            'closed': label.startswith('[Closed]'),
            'description': re_sub('\\s+', ' ', str(item.get('title') or '')).strip()[:300],
            'shared': shared(node_id)[:10],
        })

def by_overlap(items):
    order = sorted([(-len(x['shared']), -x['id'], i) for i, x in enumerate(items)])
    return [items[o[2]] for o in order]

alerts = by_overlap(alerts)
cases = by_overlap(cases)

lines = []
if cases:
    lines.append('Cases sharing IOCs or assets with this alert:')
    for c in cases[:limit]:
        state = ' (closed)' if c['closed'] else ''
        lines.append(f"- Case #{c['id']}{state}: {c['description'] or 'no description'}; shares {', '.join(c['shared']) or 'indicators'}")
if alerts:
    lines.append(f"Alerts of the last {inputs.get('days')} days sharing IOCs or assets with this alert:")
    for a in alerts[:limit]:
        state = 'closed' if a['closed'] else 'open'
        verdict = f", {a['resolution']}" if a['resolution'] else ''
        lines.append(f"- Alert #{a['id']} ({state}{verdict}): {a['title']}; shares {', '.join(a['shared']) or 'indicators'}")
if not lines:
    lines.append('No alert or case shares an IOC or an asset with this alert.')

ioc_uuids = [str(i.get('ioc_uuid')) for i in alert.get('iocs') or [] if is_dict(i) and i.get('ioc_uuid')]
asset_uuids = [str(a.get('asset_uuid')) for a in alert.get('assets') or [] if is_dict(a) and a.get('asset_uuid')]
result = {
    'title': str(alert.get('alert_title') or f"Alert #{inputs.get('alert_id')}")[:200],
    'alerts': alerts[:limit],
    'cases': cases[:limit],
    'alert_count': len(alerts),
    'case_count': len(cases),
    'open_case_ids': [c['id'] for c in cases if not c['closed']],
    'ioc_uuids': ioc_uuids,
    'asset_uuids': asset_uuids,
    'text': '\n'.join(lines),
}

out = inputs.get('verdict') if is_dict(inputs.get('verdict')) else {}
verdict = str(out.get('verdict') or '').strip().lower()
open_cases = inputs.get('open_case_ids') or []
missing = []
for item in out.get('missing') or []:
    if is_str(item) and item.strip() and len(missing) < 8:
        missing.append(item.strip()[:60])

route = 'review'
note = ''
target = None
title = ''
resolution = 'Legitimate' if str(out.get('benign_kind') or '') == 'legitimate' else 'False Positive'
if verdict == 'benign':
    route = 'close'
elif verdict == 'merge':
    text = str(out.get('target_case_id') if out.get('target_case_id') is not None else '').strip()
    target = int(text) if re_fullmatch('\\d+', text) is not None else None
    if target is not None and target in open_cases:
        route = 'merge'
    else:
        note = f"The AI proposed merging into case #{text or '?'}, which is not one of the open cases sharing indicators with this alert."
        target = None
elif verdict == 'escalate':
    route = 'escalate'
    title = str(out.get('case_title') or '').strip() or f"Alert #{inputs.get('alert_id')}: {inputs.get('title')}"
    title = title[:150]
elif verdict == 'needs_info':
    if missing and not inputs.get('asked'):
        route = 'ask'
    elif inputs.get('asked'):
        note = 'The analyst already answered once; the AI still lacks information.'
    else:
        note = 'The AI needs more information but did not say which.'

result = {'route': route, 'verdict': verdict or 'unknown', 'target_case_id': target, 'case_title': title,
          'resolution': resolution, 'missing': missing, 'note': note}

taxonomies = inputs.get('taxonomies') if is_dict(inputs.get('taxonomies')) else {}

def find(items, names):
    # Statuses and resolutions are editable: match them by name
    for wanted in names:
        for item in items or []:
            if is_dict(item) and str(item.get('name') or '').strip().lower() == str(wanted).lower():
                return item.get('id')
    return None

status = find(taxonomies.get('alert_statuses'), ['Closed'])
resolution = find(taxonomies.get('alert_resolutions'), [inputs.get('resolution'), 'False Positive'])
if status is None:
    fail('No alert status is named Closed')
if resolution is None:
    fail(f"No alert resolution is named {inputs.get('resolution')}")
result = {'status_id': status, 'resolution_id': resolution}

